package com.wangc.bill.reference.ui;

import android.app.AlertDialog;
import android.app.DatePickerDialog;
import android.content.Intent;
import android.os.Bundle;
import android.view.Gravity;
import android.view.View;
import android.view.ViewGroup;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;
import com.wangc.bill.reference.*;
import com.wangc.bill.reference.capture.AutoApps;
import org.json.JSONObject;
import java.util.*;

public final class MainActivity extends AppCompatActivity {
    private View root;private FrameLayout host;private ReferenceBottomBar bottom;private int selected;
    private long selectedDay=System.currentTimeMillis(),statsTime=System.currentTimeMillis(),customStart,customEnd;
    private int statsMode=1;private String statsKind="expense";
    private ReferenceStore store(){return ReferenceApplication.store();}
    private long bookId(){long id=ReferenceApplication.prefs().getLong("current_book",1);JSONObject b=store().book(id);if(b==null||b.optInt("archived")!=0){id=store().books().get(0).optLong("id");ReferenceApplication.prefs().edit().putLong("current_book",id).apply();}return id;}
    private String currency(){return store().book(bookId()).optString("currency");}
    @Override protected void onCreate(Bundle state){super.onCreate(state);if(state!=null){selected=state.getInt("tab");selectedDay=state.getLong("day",selectedDay);statsTime=state.getLong("statsTime",statsTime);statsMode=state.getInt("statsMode",1);}root=Ui.layout(this,"activity_main");host=Ui.view(root,"fragment_layout");bottom=Ui.view(root,"bottom_nav_view");bottom.setListener(i->{selected=i;render();});Ui.content(this,root);}
    @Override protected void onResume(){super.onResume();if(root!=null)render();}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putInt("tab",selected);out.putLong("day",selectedDay);out.putLong("statsTime",statsTime);out.putInt("statsMode",statsMode);}
    private void render(){host.removeAllViews();View page=switch(selected){case 1->calendar();case 2->assets();case 3->statistics();case 4->mine();default->home();};host.addView(page,new FrameLayout.LayoutParams(-1,-1));bottom.select(selected);}
    private void records(RecyclerView list,List<JSONObject> data,View header){list.setLayoutManager(new LinearLayoutManager(this));list.setAdapter(new RecordAdapter(data,header,row->Ui.edit(this,row.optLong("id"),null)));}
    private View home(){View v=Ui.layout(this,"fragment_home");Ui.text(v,"account_book_name",store().book(bookId()).optString("name"));Ui.image(v,"account_book_icon","ic_main_account_book");Ui.click(v,"account_book_layout",this::chooseBook);Ui.click(v,"btn_search",()->Ui.page(this,"search"));Ui.click(v,"btn_more",()->new AlertDialog.Builder(this).setItems(new String[]{"账本管理","预算设置","自动记账","回收站"},(d,w)->Ui.page(this,new String[]{"books","budget","capture","trash"}[w])).show());Ui.hide(v,"right_drawer_layout","btn_add_bill");
        View h=Ui.layout(this,"item_home_header");Ui.hide(h,"backup_tip","huawei_tip","category_type_tip","year_info_tip","comment_tip","module_list");Ui.show(h,"auto_tip",!AutoApps.enabled());Ui.click(h,"auto_tip",()->Ui.page(this,"capture"));Ui.click(h,"auto_tip_close",()->Ui.hide(h,"auto_tip"));
        View bg=Ui.view(h,"home_background");if(bg!=null)bg.setBackgroundResource(Ui.res(this,"mipmap","bg_main"));long[] range=Ui.month(System.currentTimeMillis());JSONObject t=store().totals(bookId(),range[0],range[1]);Ui.text(h,"month_pay",Money.text(t.optLong("pay"),currency()));Ui.text(h,"month_income",Money.text(t.optLong("income"),currency()));Ui.text(h,"month_balance",Money.text(t.optLong("income")-t.optLong("pay"),currency()));long budget=store().book(bookId()).optLong("budget");Ui.text(h,"month_budget",budget>0?Money.text(budget-t.optLong("budget_pay"),currency()):"点击设置");Ui.click(h,"budget_setting",()->Ui.page(this,"budget"));Ui.click(h,"add_bill_btn",()->Ui.edit(this,0,null));
        List<JSONObject> data=store().transactions(bookId(),0,Long.MAX_VALUE,null,false);Ui.show(v,"tip_layout",data.isEmpty());records(Ui.view(v,"data_list"),data,h);return v;}
    private void chooseBook(){List<JSONObject> books=store().books();String[] labels=new String[books.size()+1];for(int i=0;i<books.size();i++)labels[i]=books.get(i).optString("name")+" · "+books.get(i).optString("currency");labels[books.size()]="账本管理";new AlertDialog.Builder(this).setTitle("选择账本").setItems(labels,(d,w)->{if(w==books.size())Ui.page(this,"books");else{ReferenceApplication.prefs().edit().putLong("current_book",books.get(w).optLong("id")).apply();render();}}).show();}
    private View calendar(){View v=Ui.layout(this,"fragment_calendar");ReferenceCalendar calendar=Ui.view(v,"calendarView");calendar.configure(selectedDay,time->{selectedDay=time;render();});Ui.text(v,"month",Ui.date(selectedDay,"yyyy年MM月"));Ui.click(v,"month",()->pickDate(selectedDay,time->{selectedDay=time;render();}));Ui.click(v,"back_today",()->{selectedDay=System.currentTimeMillis();render();});Ui.click(v,"add_bill",()->startActivity(new Intent(this,EditorActivity.class).putExtra("time",selectedDay)));Ui.click(v,"btn_more",()->Ui.page(this,"plans"));Ui.hide(v,"repayment_list","date_lunar_text");long[] day=Ui.day(selectedDay),month=Ui.month(selectedDay);JSONObject t=store().totals(bookId(),day[0],day[1]),m=store().totals(bookId(),month[0],month[1]);Ui.text(v,"date_text",Ui.date(selectedDay,"MM月dd日 EEEE"));Ui.text(v,"income",Money.text(t.optLong("income"),currency()));Ui.text(v,"pay",Money.text(t.optLong("pay"),currency()));Ui.text(v,"balance",Money.text(t.optLong("income")-t.optLong("pay"),currency()));Ui.text(v,"month_income",Money.text(m.optLong("income"),currency()));Ui.text(v,"month_pay",Money.text(m.optLong("pay"),currency()));Ui.text(v,"month_balance",Money.text(m.optLong("income")-m.optLong("pay"),currency()));List<JSONObject> data=store().transactions(bookId(),day[0],day[1],null,false);Ui.show(v,"tip_layout",data.isEmpty());records(Ui.view(v,"data_list"),data,null);return v;}
    private View assets(){View v=Ui.layout(this,"fragment_asset");Ui.hide(v,"text_tip_layout","stock_layout");View banner=Ui.view(v,"asset_background");if(banner!=null)banner.setBackgroundResource(Ui.res(this,"mipmap","bg_asset"));List<JSONObject> accounts=store().accounts();long positive=0,debt=0;for(JSONObject a:accounts)if(a.optString("currency").equals("CNY")){long n=a.optLong("balance");if(n>=0)positive+=n;else debt-=n;}Ui.text(v,"net_assets_title","净资产 (CNY)");Ui.text(v,"net_assets",Money.text(positive-debt,"CNY"));Ui.text(v,"deposit",Money.text(positive,"CNY"));Ui.text(v,"liabilities",Money.text(debt,"CNY"));Ui.click(v,"num_hide_layout",()->{boolean hidden=ReferenceApplication.prefs().getBoolean("hide_balances",false);ReferenceApplication.prefs().edit().putBoolean("hide_balances",!hidden).apply();render();});if(ReferenceApplication.prefs().getBoolean("hide_balances",false))for(String id:new String[]{"net_assets","deposit","liabilities"})Ui.text(v,id,"****");Ui.click(v,"ic_asset_setting",()->Ui.page(this,"accounts"));Ui.click(v,"reimbursement_layout",()->Ui.page(this,"reimbursement"));Ui.click(v,"lend_layout",()->Ui.page(this,"lending"));Ui.text(v,"reimbursement_num",Money.text(financial("reimbursement",false),"CNY"));Ui.text(v,"reimbursement_end_num",Money.text(financial("reimbursement",true),"CNY"));Ui.text(v,"lend_num",Money.text(financial("lend",false),"CNY"));Ui.text(v,"borrow_num",Money.text(financial("borrow",false),"CNY"));Ui.show(v,"tip_layout",accounts.isEmpty());RecyclerView list=Ui.view(v,"data_List");list.setLayoutManager(new LinearLayoutManager(this));list.setNestedScrollingEnabled(false);list.setAdapter(new RecyclerView.Adapter<SimpleHolder>(){
            @Override public int getItemCount(){return accounts.size();}@Override public SimpleHolder onCreateViewHolder(ViewGroup p,int t){return new SimpleHolder(Ui.layout(p.getContext(),"item_asset"));}@Override public void onBindViewHolder(SimpleHolder h,int at){JSONObject a=accounts.get(at);Ui.hide(h.itemView,"stock_info","last_day_income_title","last_day_income","up_down_num","credit_quota");Ui.text(h.itemView,"name",a.optString("name"));Ui.text(h.itemView,"remark",a.optString("currency"));Ui.text(h.itemView,"cost",Money.text(a.optLong("balance"),a.optString("currency")));Ui.image(h.itemView,"icon",a.optString("name").contains("微信")?"ic_parent_wechat":a.optString("name").contains("支付宝")?"ic_parent_alipay":"ic_asset_cash");h.itemView.setOnClickListener(x->startActivity(new Intent(MainActivity.this,ManagerActivity.class).putExtra("page","account_detail").putExtra("id",a.optLong("id"))));}});plus(v,()->Ui.page(this,"new_account"));return v;}
    private long financial(String type,boolean settled){long total=0;for(JSONObject row:store().query("SELECT id,amount FROM transactions WHERE deleted=0 AND currency='CNY' AND financial_type=?",type)){long left=store().outstanding(row.optLong("id"));total+=settled?row.optLong("amount")-left:left;}return total;}
    private void plus(View v,Runnable action){if(!(v instanceof android.widget.RelativeLayout group))return;TextView add=Ui.label(this,"+",30);add.setTextColor(-1);add.setGravity(Gravity.CENTER);add.setBackground(Ui.rounded(Ui.GREEN,30,this));android.widget.RelativeLayout.LayoutParams p=new android.widget.RelativeLayout.LayoutParams(Ui.dp(this,54),Ui.dp(this,54));p.addRule(android.widget.RelativeLayout.ALIGN_PARENT_END);p.addRule(android.widget.RelativeLayout.ALIGN_PARENT_BOTTOM);p.setMargins(0,0,Ui.dp(this,20),Ui.dp(this,20));group.addView(add,p);add.setContentDescription("新增账户");add.setOnClickListener(x->action.run());}
    private View mine(){View v=Ui.layout(this,"fragment_my");Ui.image(v,"second_background","bg_my_two");Ui.image(v,"my_background","bg_my_one");Ui.image(v,"photo_image","ic_launcher");Ui.hide(v,"vip_icon","spin_kit","tip_layout");Ui.text(v,"nick_name",ReferenceApplication.prefs().getString("nickname","本地用户"));long since=store().scalar("SELECT MIN(created) n FROM books");long days=Math.max(1,(System.currentTimeMillis()-since)/86400000+1);long count=store().scalar("SELECT COUNT(*) n FROM transactions WHERE deleted=0");Ui.text(v,"record_day_num","坚持记账的第"+days+"天\n已记录"+count+"条账单");Ui.text(v,"remote_backup_status","实验版未接入，数据仅存本地");Ui.text(v,"backup_count","本地共 "+count+" 条账单");
        String[][] routes={{"auto_manager","capture"},{"cycle_manager","plans"},{"dream_list","goals"},{"book_manager","books"},{"tag_manager","tags"},{"category_manager","categories"},{"setting","settings"},{"data_backup","backup"},{"import_manager","import"},{"bill_file","attachments"},{"theme_setting","theme"},{"widget_setting","widgets"},{"user_guide","help"},{"feed_back","diagnostics"},{"about_us","about"}};for(String[] route:routes)Ui.click(v,route[0],()->Ui.page(this,route[1]));for(String name:new String[]{"open_vip_layout","ai_type_self","remote_backup_layout","remote_backup_more","invitation","evaluate"})Ui.click(v,name,()->Ui.offline(this));Ui.click(v,"user_info_layout",()->Ui.page(this,"profile"));return v;}
    private View statistics(){View v=Ui.layout(this,"fragment_statistics");String[] ids={"normal_bill_btn","month_bill_btn","year_bill_btn","self_bill_btn"};for(int i=0;i<ids.length;i++){final int index=i;TextView t=Ui.view(v,ids[i]);if(t!=null)t.setTextColor(i==statsMode?Ui.GREEN:Ui.color(this,"black",0xff000000));Ui.click(v,ids[i],()->{statsMode=index;if(index==3&&customEnd==0){long[] m=Ui.month(statsTime);customStart=m[0];customEnd=m[1];}render();});}Ui.click(v,"btn_more",()->Ui.page(this,"budget"));FrameLayout pager=Ui.view(v,"statistics_pager");String template=statsMode==0?"fragment_statistics_normal":statsMode==2?"fragment_statistics_year":"fragment_statistics_month";View chart=Ui.layout(this,template);pager.addView(chart,new FrameLayout.LayoutParams(-1,-1));long[] range=statsMode==2?Ui.year(statsTime):statsMode==3?new long[]{customStart,customEnd}:Ui.month(statsTime);if(statsMode==0){long[] d=Ui.day(System.currentTimeMillis());range=new long[]{d[0]-6*86400000L,d[1]};}JSONObject totals=store().totals(bookId(),range[0],range[1]);String cur=currency();Ui.text(chart,"pay_num",Money.text(totals.optLong("pay"),cur));Ui.text(chart,"income_num",Money.text(totals.optLong("income"),cur));Ui.text(chart,"balance_num",Money.text(totals.optLong("income")-totals.optLong("pay"),cur));Ui.text(chart,"current_year",statsMode==3?Ui.date(range[0],"MM.dd")+"—"+Ui.date(range[1]-1,"MM.dd"):Ui.date(statsTime,"yyyy年"));Ui.text(chart,"total_pay","总支出："+Money.text(totals.optLong("pay"),cur));Ui.text(chart,"total_income","总收入："+Money.text(totals.optLong("income"),cur));long days=Math.max(1,(range[1]-range[0])/86400000L);Ui.text(chart,"day_pay","日均支出："+Money.text(totals.optLong("pay")/days,cur));Ui.text(chart,"day_income","日均收入："+Money.text(totals.optLong("income")/days,cur));Ui.hide(chart,"member_layout","content_tip_layout");
        final long start=range[0],end=range[1];List<JSONObject> categories=store().categoryTotals(bookId(),start,end,statsKind);plot(chart,"pie_chart","pie",categories,cur);plot(chart,"bar_chart","bar",daily(start,end,statsMode==2),cur);plot(chart,"line_chart","line",daily(start,end,statsMode==2),cur);Ui.text(chart,"bar_title",statsMode==2?"年度收支趋势":"收支趋势");Ui.text(chart,"line_title","支出趋势");Ui.text(chart,"pie_chart_check_text",statsKind.equals("expense")?"支出":"收入");Ui.click(chart,"pie_chart_check",()->{statsKind=statsKind.equals("expense")?"income":"expense";render();});Ui.click(chart,"view_all_bill",()->startActivity(new Intent(this,ManagerActivity.class).putExtra("page","range_records").putExtra("start",start).putExtra("end",end)));
        Ui.click(chart,"current_year_layout",()->{if(statsMode==3)pickDate(customStart,time->{customStart=Ui.day(time)[0];pickDate(customEnd-1,last->{customEnd=Ui.day(last)[1];if(customEnd<=customStart)customEnd=Ui.day(customStart)[1];render();});});else pickDate(statsTime,time->{statsTime=time;render();});});
        RecyclerView months=Ui.view(chart,"month_list");if(months!=null)horizontalChoices(months,12,index->{Calendar c=Calendar.getInstance();c.setTimeInMillis(statsTime);c.set(Calendar.DAY_OF_MONTH,1);c.set(Calendar.MONTH,index);statsTime=c.getTimeInMillis();render();},false);RecyclerView years=Ui.view(chart,"year_list");if(years!=null)horizontalChoices(years,7,index->{Calendar c=Calendar.getInstance();c.setTimeInMillis(statsTime);c.set(Calendar.DAY_OF_MONTH,1);c.set(Calendar.YEAR,Calendar.getInstance().get(Calendar.YEAR)-5+index);statsTime=c.getTimeInMillis();render();},true);
        RecyclerView data=Ui.view(chart,"bill_data");if(data!=null){data.setLayoutManager(new LinearLayoutManager(this));data.setNestedScrollingEnabled(false);data.setAdapter(new SummaryAdapter(categories,cur));}
        for(String id:new String[]{"day_form_data","month_form_data"}){RecyclerView form=Ui.view(chart,id);if(form!=null){form.setLayoutManager(new LinearLayoutManager(this));form.setNestedScrollingEnabled(false);form.setAdapter(new SummaryAdapter(daily(start,end,statsMode==2),cur));}}
        List<JSONObject> tagData=store().query("SELECT g.name,SUM(t.amount) amount FROM tags g JOIN transaction_tags x ON x.tag_id=g.id JOIN transactions t ON t.id=x.transaction_id WHERE t.book_id=? AND t.deleted=0 AND t.not_total=0 AND t.kind=? AND t.time>=? AND t.time<? GROUP BY g.id ORDER BY amount DESC",""+bookId(),statsKind,""+start,""+end);plot(chart,"tag_pie_chart","pie",tagData,cur);RecyclerView tagList=Ui.view(chart,"tag_data");if(tagList!=null){tagList.setLayoutManager(new LinearLayoutManager(this));tagList.setNestedScrollingEnabled(false);tagList.setAdapter(new SummaryAdapter(tagData,cur));}Ui.click(chart,"tag_info",()->Ui.page(this,"tags"));Ui.click(chart,"budget_info",()->Ui.page(this,"budget"));
        if(statsMode==0){List<JSONObject> assets=new ArrayList<>();for(JSONObject a:store().accounts())if(a.optString("currency").equals(cur)&&a.optLong("balance")>0)assets.add(Json.object("name",a.optString("name"),"amount",a.optLong("balance")));plot(chart,"pie_asset_chart","pie",assets,cur);long budget=store().book(bookId()).optLong("budget");long[] month=Ui.month(System.currentTimeMillis());long used=store().totals(bookId(),month[0],month[1]).optLong("budget_pay");plot(chart,"pie_budget_chart","pie",java.util.Arrays.asList(Json.object("name","已用","amount",Math.max(0,used)),Json.object("name","剩余","amount",Math.max(0,budget-used))),cur);}
        View md=Ui.view(chart,"markdown_view");if(md instanceof ViewGroup group){String key="summary_"+bookId()+"_"+statsMode+"_"+start;TextView note=Ui.label(this,ReferenceApplication.prefs().getString(key,"点击编辑记录本期总结"),14);note.setPadding(Ui.dp(this,15),Ui.dp(this,15),Ui.dp(this,15),Ui.dp(this,15));group.addView(note,new ViewGroup.LayoutParams(-1,-2));Ui.click(chart,"content_edit",()->{EditText edit=new EditText(this);edit.setText(ReferenceApplication.prefs().getString(key,""));new AlertDialog.Builder(this).setTitle("本期总结").setView(edit).setNegativeButton("取消",null).setPositiveButton("保存",(d,w)->{ReferenceApplication.prefs().edit().putString(key,edit.getText().toString()).apply();render();}).show();});Ui.click(chart,"content_copy",()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(android.content.ClipData.newPlainText("本期总结",note.getText()));Ui.toast(this,"已复制");});}
        return v;}
    private List<JSONObject> daily(long start,long end,boolean monthly){List<JSONObject> rows=new ArrayList<>();Calendar c=Calendar.getInstance();c.setTimeInMillis(start);int guard=0;while(c.getTimeInMillis()<end&&guard++<370){long first=c.getTimeInMillis();c.add(monthly?Calendar.MONTH:Calendar.DATE,1);JSONObject t=store().totals(bookId(),first,Math.min(end,c.getTimeInMillis()));rows.add(Json.object("name",Ui.date(first,monthly?"M月":"d"),"amount",t.optLong(statsKind.equals("income")?"income":"pay")));}return rows;}
    private void plot(View root,String name,String mode,List<JSONObject> values,String currency){View v=Ui.view(root,name);if(v instanceof ViewGroup group){group.removeAllViews();group.addView(new StatsChart(this,mode,values,currency),new ViewGroup.LayoutParams(-1,-1));}}
    private interface Index{void at(int index);}
    private void horizontalChoices(RecyclerView view,int count,Index click,boolean year){view.setLayoutManager(new LinearLayoutManager(this,LinearLayoutManager.HORIZONTAL,false));view.setAdapter(new RecyclerView.Adapter<SimpleHolder>(){@Override public int getItemCount(){return count;}@Override public SimpleHolder onCreateViewHolder(ViewGroup p,int t){TextView label=Ui.label(p.getContext(),"",14);label.setGravity(Gravity.CENTER);label.setLayoutParams(new RecyclerView.LayoutParams(Ui.dp(p.getContext(),year?76:56),Ui.dp(p.getContext(),42)));return new SimpleHolder(label);}@Override public void onBindViewHolder(SimpleHolder h,int i){TextView label=(TextView)h.itemView;int value=year?Calendar.getInstance().get(Calendar.YEAR)-5+i:i+1;label.setText(value+(year?"年":"月"));Calendar c=Calendar.getInstance();c.setTimeInMillis(statsTime);boolean selected=year?c.get(Calendar.YEAR)==value:c.get(Calendar.MONTH)==i;label.setTextColor(selected?Ui.GREEN:Ui.color(MainActivity.this,"black",0xff000000));label.setOnClickListener(v->click.at(i));}});Calendar c=Calendar.getInstance();c.setTimeInMillis(statsTime);view.scrollToPosition(year?5:c.get(Calendar.MONTH));}
    public interface DateResult{void value(long time);}
    public void pickDate(long initial,DateResult result){Calendar c=Calendar.getInstance();c.setTimeInMillis(initial);new DatePickerDialog(this,(v,y,m,d)->{Calendar chosen=Calendar.getInstance();chosen.set(y,m,d,12,0,0);chosen.set(Calendar.MILLISECOND,0);result.value(chosen.getTimeInMillis());},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}
    static final class SimpleHolder extends RecyclerView.ViewHolder{SimpleHolder(View view){super(view);}}
    private static final class SummaryAdapter extends RecyclerView.Adapter<SimpleHolder>{private final List<JSONObject> values;private final String currency;SummaryAdapter(List<JSONObject>v,String c){values=v;currency=c;}@Override public int getItemCount(){return values.size();}@Override public SimpleHolder onCreateViewHolder(ViewGroup p,int t){return new SimpleHolder(Ui.row(p.getContext(),"","",null));}@Override public void onBindViewHolder(SimpleHolder h,int i){LinearLayout row=(LinearLayout)h.itemView;JSONObject value=values.get(i);((TextView)row.getChildAt(0)).setText(value.optString("name")+"    "+Money.text(value.optLong("amount"),currency));}}
}
